import React from 'react';
import Question from './Question';
import { ChevronDown, ChevronRight } from 'lucide-react'; // Иконки стрелок

function Category({ category, onVote, onToggle }) {
    const totalRating = category.questions.reduce((sum, q) => sum + q.rating, 0);

    return (
        <div className="category">
            <div className="category-header" onClick={onToggle}>
                {/* Стрелка-состояние (повёрнута вниз если раскрыта) */}
                <span className="arrow">
                    {category.isOpen ? <ChevronDown size={20} /> : <ChevronRight size={20} />}
                </span>
                {/* Название категории */}
                <h2>{category.name}</h2>
                {/* Общий рейтинг категории */}
                <span className="total-rating">{totalRating >= 0 ? `+${totalRating}` : totalRating}</span>
            </div>

            {/* Список вопросов, если категория раскрыта */}
            {category.isOpen && (
                <div className="questions">
                    {category.questions.map(q => (
                        <Question
                            key={q.id}
                            question={q}
                            onVote={delta => onVote(category.id, q.id, delta)}
                        />
                    ))}
                </div>
            )}
        </div>
    );
}

export default Category;
